import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 125 Tea for two","description":"学习 have to 的时态与否定，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 125 Tea for two","description":"学习 have to 的时态与否定，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 have to 的时态与否定，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 124 Who, whom, which and that","link":"/life/english/new-concept/book-1/unit-06/lesson-124"},"next":{"text":"第一册：英语初阶 · Lesson 126 Have to and do not need to","link":"/life/english/new-concept/book-1/unit-06/lesson-126"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 124 Who, whom, which and that","link":"/life/english/new-concept/book-1/unit-06/lesson-124"},"next":{"text":"第一册：英语初阶 · Lesson 126 Have to and do not need to","link":"/life/english/new-concept/book-1/unit-06/lesson-126"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-125.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-125.md"}'),r={name:"life/english/new-concept/book-1/unit-06/lesson-125.md"};function i(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-125-tea-for-two" tabindex="-1">第一册：英语初阶 · Lesson 125 Tea for two <a class="header-anchor" href="#第一册-英语初阶-·-lesson-125-tea-for-two" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 125 Tea for two&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-126">配套课 Lesson 126</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>说明不得不做与不需要做 本课要掌握have to 的时态与否定，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>water</td><td>/ˈwɔːtə/</td><td>v.</td><td>浇水</td><td>water the plants</td></tr><tr><td>garden</td><td>/ˈɡɑːdən/</td><td>n.</td><td>花园</td><td>work in the garden</td></tr><tr><td>dry</td><td>/draɪ/</td><td>adj.</td><td>干燥的</td><td>dry soil</td></tr><tr><td>need</td><td>/niːd/</td><td>v.</td><td>需要</td><td>do not need to</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>have to work — 因客观要求而必须工作</li><li>do not need to — 没有必要</li></ul><h2 id="语法讲解-have-to-的时态与否定" tabindex="-1">语法讲解：have to 的时态与否定 <a class="header-anchor" href="#语法讲解-have-to-的时态与否定" aria-label="Permalink to &quot;语法讲解：have to 的时态与否定&quot;">​</a></h2><p>have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I had to water the plants before work.</p></blockquote><p>上班前我不得不给植物浇水。</p><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>doesn&#39;t 后接 have to 而非 has to；否定 have to 表不必。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“I had to water the plants before work.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I had to water the plants before work. She does not have to work this Sunday.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“说明不得不做与不需要做”写两至三句，再读给同伴听。至少使用一次have to 的时态与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。 Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填过去形式：Yesterday I ___ to water the plants.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“上班前我不得不给植物浇水。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I had to water the plants before work.</p><p><strong>解析：</strong> Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：She does not have to work this Sunday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 她这周日不必工作。</p><p><strong>解析：</strong> Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：have to 的时态与否定。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-124">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-126">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
